#include <bits/stdc++.h>
using namespace std;

class first {
public:
    int gcd(int a, int b) {
        if (b == 0) return a;
        return gcd(b, a % b);
    }

    void go() {
        ios::sync_with_stdio(false);
        cin.tie(nullptr);
        string test;
        if (!getline(cin, test) || test.empty()) return;

        stringstream ss(test);
        int tt;
        ss >> tt;
        vector<int> a(3), b(3);
        for (int i = 0; i < 3; ++i) {
            ss >> a[i];
        }
        for (int i = 0; i < 3; ++i) {
            ss >> b[i];
        }

        int alicemax = 0, bobmax = 0;

        if (a[0] != 0) {
            alicemax += std::min(a[0], b[1]);
        }
        if (a[1] != 0) {
            alicemax += std::min(a[1], b[2]);
        }
        if (a[2] != 0) {
            alicemax += std::min(a[2], b[0]);
        }

        vector<int> b_copy = b; // To modify b without affecting original
        if (b_copy[0] != 0) {
            int min_val = std::min(b_copy[0], a[1]);
            bobmax += min_val;
            b_copy[0] -= min_val;
            if (b_copy[0] != 0) {
                min_val = std::min(b_copy[0], a[0]);
                bobmax += min_val;
                b_copy[0] -= min_val;
            }
        }
        if (b_copy[1] != 0) {
            int min_val = std::min(b_copy[1], a[2]);
            bobmax += min_val;
            b_copy[1] -= min_val;
            if (b_copy[1] != 0) {
                min_val = std::min(b_copy[1], a[1]);
                bobmax += min_val;
                b_copy[1] -= min_val;
            }
        }
        if (b_copy[2] != 0) {
            int min_val = std::min(b_copy[2], a[0]);
            bobmax += min_val;
            b_copy[2] -= min_val;
            if (b_copy[2] != 0) {
                min_val = std::min(b_copy[2], a[2]);
                bobmax += min_val;
                b_copy[2] -= min_val;
            }
        }

        cout << (tt - bobmax) << " " << alicemax << "\n";
    }
};

int main() {
    first obj;
    obj.go();
    return 0;
}
